// --- END EMBEDDED SPRITE ---

// Pure-JS RFC 4648 base64 decoder (the sandbox `atob` is UTF-8 text only and
// would corrupt binary). Returns a Uint8Array.
function base64ToBytes(b64) {
  const clean = b64.replace(/\s+/g, '')
  const out = new Uint8Array((clean.length >> 2) * 3)
  let o = 0
  for (let i = 0; i < clean.length; i += 4) {
    const c0 = B64.indexOf(clean.charAt(i))
    const c1 = B64.indexOf(clean.charAt(i + 1))
    const c2 = i + 2 < clean.length && clean.charAt(i + 2) !== '=' ? B64.indexOf(clean.charAt(i + 2)) : -1
    const c3 = i + 3 < clean.length && clean.charAt(i + 3) !== '=' ? B64.indexOf(clean.charAt(i + 3)) : -1
    const n = (c0 << 18) + (c1 << 12) + (c2 === -1 ? 0 : (c2 << 6)) + (c3 === -1 ? 0 : c3)
    out[o++] = (n >> 16) & 255
    if (c2 !== -1) out[o++] = (n >> 8) & 255
    if (c3 !== -1) out[o++] = n & 255
  }
  return out.subarray(0, o)
}

// bytes -> latin1 "binary" string, so the host-realm HTTP response can be
// written with res.end(binary, 'latin1') without needing a cross-realm Buffer.
function bytesToBinary(bytes) {
  let s = ''
  const CHUNK = 0x8000
  for (let i = 0; i < bytes.length; i += CHUNK) {
    s += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK))
  }
  return s
}

let spriteBytesCache = null
let spriteBinaryCache = null
let spriteCleanCache = null

function spriteBytes() {
  if (spriteBytesCache === null) spriteBytesCache = base64ToBytes(SPRITE_B64)
  return spriteBytesCache
}
function spriteBinary() {
  if (spriteBinaryCache === null) spriteBinaryCache = bytesToBinary(spriteBytes())
  return spriteBinaryCache
}
function spriteClean() {
  if (spriteCleanCache === null) spriteCleanCache = SPRITE_B64.replace(/\s+/g, '')
  return spriteCleanCache
}

return {
  name: 'silverhand-pet-host',
  inject: ['webServer', 'agents'],

  apply(ctx) {
    // ---- agent state ------------------------------------------------------
    // `transient` is a short-lived reaction that overrides the derived
    // running/idle baseline until it expires.
    let lastStatus = 'idle'
    let transient = null // { state, until }
    let waitingUntil = 0

    function setTransient(state, ms) {
      transient = { state, until: Date.now() + ms }
    }

    function currentState() {
      if (Date.now() < waitingUntil) return 'waiting'
      if (transient !== null) {
        if (Date.now() < transient.until) return transient.state
        transient = null
      }
      const agents = ctx.agents.list()
      for (let i = 0; i < agents.length; i += 1) {
        if (agents[i].status === 'running') return 'running'
      }
      return 'idle'
    }

    const offStatus = ctx.on('agent/status', (payload) => {
      waitingUntil = 0
      const next = payload && payload.status
      if (lastStatus === 'running' && next === 'idle') setTransient('jumping', 1600)
      if (next === 'idle' || next === 'running') lastStatus = next
    })
    const offError = ctx.on('agent/error', () => {
      waitingUntil = 0
      setTransient('failed', 2600)
    })
    const offResult = ctx.on('tools/result', () => {
      waitingUntil = 0
      setTransient('review', 1800)
    })
    const offCreated = ctx.on('agent/created', () => setTransient('waving', 3200))
    const offSessionStart = ctx.on('agent/session-start', () => setTransient('waving', 3200))
    // Observe the approval waterfall WITHOUT vetoing it: set "waiting", then
    // defer to the real answerers via next(). Untagged listeners (dynamic
    // packages) are admitted for every agent-scoped dispatch, so this fires
    // for approvals across all sessions.
    const offApproval = ctx.on('approval/request', (req, next) => {
      waitingUntil = Date.now() + 60000
      return next()
    })

    // ---- HTTP route (primary delivery) ------------------------------------
    const offRoute = ctx.webServer.register({
      kind: 'exact',
      path: ROUTE_PATH,
      handler: (_req, res) => {
        const bytes = spriteBytes()
        res.writeHead(200, {
          'Content-Type': 'image/webp',
          'Content-Length': String(bytes.length),
          'Cache-Control': 'public, max-age=86400',
        })
        res.end(spriteBinary(), 'latin1')
      },
    })

    // ---- private RPC for the Client half ----------------------------------
    const offState = harness.handle('getState', () => ({ state: currentState() }))
    const offSprite = harness.handle('getSprite', () => ({ dataUri: 'data:image/webp;base64,' + spriteClean() }))

    // ---- cleanup ----------------------------------------------------------
    return () => {
      offState()
      offSprite()
      offRoute()
      offApproval()
      offSessionStart()
      offCreated()
      offResult()
      offError()
      offStatus()
    }
  },
}
